        // command". Keep this before any `options.parsingResult` reads so local-exec
        // does not parse-match against an allowlist that cannot contain a match.
        if (await this.shouldPromptForEmptyPlainShellAllowlist(command, perms)) {
            permissions_service_logger.info(ctx, "Shell permissions: prompting for empty allowlist", {
                toolCallId: options.toolCallId,
                approvalMode,
                userConfiguredPolicyType: sandboxPolicyTypeForLogging(userConfiguredPolicy),
                requestedPolicyType: sandboxPolicyTypeForLogging(requestedPolicy),
                hasSmartModeApprovalReason: options.smartModeApprovalReason !== undefined,
                hasSmartModeApprovalRequestId: options.smartModeApprovalRequestId !== undefined,
            });
            return await this.requestApprovalForEmptyShellAllowlist(command, options, requestedPolicy ?? userConfiguredPolicy);
        }
        // Extract command information
        const executableCommands = options.parsingResult.executableCommands;
        const hasRedirects = options.parsingResult.hasRedirects;
        // Field name is wire-compatible with the original /dev/null-only signal,
        // but the parser now sets it for any redirect graph that is safe to offer
        // as an allowlist prompt (original stdout/stderr or /dev/null only).
        const allRedirectsAreAllowlistSafe = options.parsingResult.allRedirectsAreDevNull === true;
        const parsingFailed = options.parsingResult.parsingFailed;
        const classifierResult = options.classifierResult;
        const smartModeApprovalReason = options.smartModeApprovalReason;
        const smartModeApprovalRequestId = options.smartModeApprovalRequestId;
        const usableClassifierResult = classifierResult !== undefined &&
            !classifierResult.classificationFailed &&
            classifierResult.commands.length > 0
            ? classifierResult
            : undefined;
        const smartAllowlistClassifierCommands = approvalMode === "allowlist" && (perms.smartAllowlistEnabled ?? false)
