            // colon-syntax and glob semantics (Shell(npm:install*), Shell(curl:*))
            // because we still delegate to `matchesShell` per form.
            const commandIsAllowlisted = commandMatchFormsPerCommand.map(forms => userAllowlistEntries.some(entry => forms.some(form => this.matchesShell(entry, form))));
            const allInAllowlist = commandIsAllowlisted.every(Boolean);
            // Partition classifier commands into allowed vs not-allowed. Done as a
            // single index walk so the raw-name list and classifier-command list
